Ltac flag_pend_restrict_public_entry :=
  match goal with
  | H : FlagPendInactiveFirstProgram.flag_pend_public_entry
      ?environment ?critical ?sg ?caller ?call ?mask ?i ?pgrp ?requested ?mode ?delay ?before ?X |- _ =>
      let Horiginal := fresh "H_original_entry" in
      pose proof (FlagPendInactiveFirstProgram.flag_pend_public_entry_restrict
        environment critical sg caller call mask i pgrp requested mode delay before X H) as Horiginal
  | _ => idtac
  end.

